/**
 * Monthly prediction — combines Sun transit periods (one per sidereal sign,
 * generated by services/varshaphal.py --monthly) with Sarvashtavarga points
 * and Jupiter's house-from-Moon to produce a structured per-period reading.
 *
 * Each period emits a `prediction` object with four life-area categories
 *   { work, health, relationship, investment }
 * formed by joining the Sun-house-from-Moon × band template with the
 * Jupiter-house-from-Moon modifier. Templates live in
 * db/monthly-predictions.json so wording can be tuned without code changes.
 */

const { getMonthlyRaw } = require('./varshaphal');
const predictions = require('../db/monthly-predictions.json');

// Sarvashtavarga point bands. Standard cutoffs in classical Vedic literature:
// average for any sign is ~28 (337 / 12); ≥30 is auspicious, <25 is weak.
const HIGH_BINDU = 30;
const LOW_BINDU = 25;

const CATEGORIES = ['work', 'health', 'relationship', 'investment'];

function bandFor(points) {
  if (points >= HIGH_BINDU) return 'high';
  if (points < LOW_BINDU) return 'low';
  return 'neutral';
}

function emptyPrediction() {
  return Object.fromEntries(CATEGORIES.map(c => [c, '']));
}

function predictionForPeriod(period) {
  const sunHouse = String(period.sunHouseFromMoon);
  const jupHouse = String(period.jupiterHouseFromMoon);
  const block = predictions.sunFromMoon[sunHouse];
  const band = bandFor(period.sarvashtavargaPoints);

  if (!block) {
    return { band, theme: '', prediction: emptyPrediction() };
  }
  // The new schema is { high|neutral|low: { work, health, relationship, investment } }.
  // Fall back to neutral if the requested band is missing for any reason.
  const sun = block[band] || block.neutral || {};
  const jup = predictions.jupiterFromMoonModifier[jupHouse] || {};

  const prediction = {};
  for (const c of CATEGORIES) {
    const sunText = (sun[c] || '').trim();
    const jupText = (jup[c] || '').trim();
    prediction[c] = [sunText, jupText].filter(Boolean).join(' ');
  }

  return {
    band,
    theme: block.theme || '',
    prediction,
  };
}

async function getMonthlyPrediction(birthData, year) {
  const raw = await getMonthlyRaw(birthData, year);
  const periods = raw.periods.map(p => {
    const pred = predictionForPeriod(p);
    return {
      ...p,
      band: pred.band,
      theme: pred.theme,
      prediction: pred.prediction,
    };
  });

  return {
    year,
    varshapravesh: raw.varshapravesh,
    nextVarshapravesh: raw.nextVarshapravesh,
    natalMoonSign: raw.natalMoonSign,
    natalMoonSignVedic: raw.natalMoonSignVedic,
    periods,
  };
}

module.exports = {
  getMonthlyPrediction,
  predictionForPeriod,
  bandFor,
  CATEGORIES,
};
